using System;
using System.Collections.Generic;
using System.IO;
using Convoy.AI;
using Convoy.Level;
using Convoy.Presentation;
using Convoy.Race;
using Convoy.Vehicle;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.SceneManagement;
using Object = UnityEngine.Object;

namespace Convoy.Editor
{
    /// <summary>
    /// TR-01c integration (spec docs/specs/TR-01.md, D-030, D-031): wires the runtime side of the Páramo into a scene
    /// already generated by <see cref="ParamoTerrainGenerator"/>:
    ///   1. <see cref="WorldVariationRunner"/> + <see cref="ParamoAtmosphere"/> on <c>Paramo_Runtime/WorldVariation</c>,
    ///      pointing at the generated shortcut rockfalls and mine slots;
    ///   2. one <see cref="RacingLine"/> per rival route (waypoints ~12 m apart on the carved road, ending at the
    ///      Monolith plateau edge) and one AI Jackal per line at its map-edge spawn (<see cref="AiRivalSetup"/>);
    ///   3. <see cref="RouteRecoveryPoints"/> on the player Jackal from all main roads + shortcuts (chasm gap excluded),
    ///      so V-02 resets go back to a road.
    /// Idempotent: everything lives under the root <c>Paramo_Runtime</c> (found by name and updated in place) or on the
    /// player Jackal. Objects generated by TR-01b are only referenced, never changed (the runner toggles them at play
    /// time). Order: run AFTER the terrain generator: it rebuilds <c>Paramo_Generated</c>, which breaks the references
    /// made here. The only asset written is <c>Paramo_WorldVariation</c> (non-shortcut ids removed, see SanitiseVariation).
    /// </summary>
    public static class TR01_ParamoRuntimeSetup
    {
        public const string RuntimeRootName = "Paramo_Runtime";
        public const string LayoutPath = "Assets/_Convoy/Config/Level/Paramo_01_Layout.asset";
        public const string VariationPath = "Assets/_Convoy/Config/Level/Paramo_WorldVariation.asset";

        // AI waypoint target spacing (spec: RacingLine waypoints every 12 m; AC 9: 10-15 m apart).
        public const float RivalWaypointSpacing = 12f;
        // Rival lanes stay this far inside the road edge so the outer wheels never ride the shoulder.
        private const float RivalLaneEdgeMargin = 1f;
        // Recovery points every 4 m: dense enough that "nearest" is never more than 2 m off the road centre.
        private const float RecoverySpacing = 4f;
        // Chasm: no recovery point from the near lip to this far past the far lip (the landing and its cut-down run-out),
        // so a reset never puts a car in, or right beside, the hole it just fell into.
        private const float ChasmLandingExclusion = 20f;
        private const float ChasmEdgeMargin = 4f;
        // Generated terrain vs. the layout asset: differences above this mean the generator was not re-run.
        private const float TerrainMismatchTolerance = 0.5f;

        private const string PlayerName = "Jackal";
        private const string WorldName = "WorldVariation";
        private const string LinesGroup = "RacingLines";
        private const string RivalsGroup = "Rivals";

        [MenuItem("Convoy/Integration/TR-01c Páramo Runtime Setup")]
        public static void ApplyToDefaultScene()
        {
            ApplyToScene(ParamoTerrainGenerator.DefaultScenePath);
        }

        /// <summary>
        /// Overwrites <c>Paramo_01_Layout.asset</c> with <see cref="ParamoLayoutDefaults"/>. The generator never
        /// overwrites an existing layout (it is the tuning source of truth), so code-side layout fixes (TR-01c review)
        /// only reach the scene through this explicit, confirmed step. Then re-run the generator and the setup.
        /// </summary>
        [MenuItem("Convoy/Terrain/Reset Páramo_01 Layout To Defaults")]
        public static void ResetLayoutToDefaults()
        {
            var layout = AssetDatabase.LoadAssetAtPath<TerrainLayout>(LayoutPath);
            if (layout == null)
            {
                Debug.LogWarning($"[TR-01c] {LayoutPath} not found: the generator will create it from defaults.");
                return;
            }
            if (!Application.isBatchMode && !EditorUtility.DisplayDialog("Reset Páramo layout",
                    $"Overwrite {LayoutPath} with the code defaults? Any tuning in the asset is lost.", "Reset", "Cancel"))
                return;
            layout.data = ParamoLayoutDefaults.Create();
            EditorUtility.SetDirty(layout);
            AssetDatabase.SaveAssets();
            Debug.Log($"[TR-01c] {LayoutPath} reset to ParamoLayoutDefaults. Now run Convoy/Terrain/Generate Páramo_01, " +
                      "then Convoy/Integration/TR-01c Páramo Runtime Setup.");
        }

        /// <summary>D-030 entry point: opens <paramref name="scenePath"/>, wires the Páramo runtime and saves the scene.</summary>
        public static void ApplyToScene(string scenePath)
        {
            var layoutAsset = AssetDatabase.LoadAssetAtPath<TerrainLayout>(LayoutPath);
            var variation = AssetDatabase.LoadAssetAtPath<WorldVariationConfig>(VariationPath);
            if (layoutAsset == null || variation == null)
            {
                Debug.LogError($"[TR-01c] {LayoutPath} / {VariationPath} missing: run Convoy/Terrain/Generate Páramo_01 first.");
                return;
            }
            if (!File.Exists(scenePath))
            {
                Debug.LogError($"[TR-01c] {scenePath} not found: run Convoy/Terrain/Generate Páramo_01 first.");
                return;
            }
            if (!OpenScene(scenePath, out Scene scene)) return;

            GameObject generated = FindRoot(scene, ParamoTerrainGenerator.RootName);
            if (generated == null)
            {
                Debug.LogError($"[TR-01c] {scenePath} has no {ParamoTerrainGenerator.RootName}: run the generator first.");
                return;
            }

            TerrainLayoutData layout = layoutAsset.data;
            var log = new List<string>();
            SanitiseVariation(variation, layout, log);

            // Same pure synthesis the generator used: the AI lines and recovery points sit exactly on the carved roads.
            HeightField heights = TerrainSynthesis.Build(layout);
            CheckTerrainMatches(scene, heights, layout, log);

            Transform root = AiRivalSetup.EnsureRoot(scene, RuntimeRootName);
            VehicleController player = FindPlayer(scene);

            SetupWorldVariation(root, generated.transform, variation, layout, log);
            int rivals = SetupRivals(root, layout, heights, player, log);
            SetupRecovery(player, layout, heights, log);

            EditorSceneManager.MarkSceneDirty(scene);
            if (!EditorSceneManager.SaveScene(scene, scenePath))
            {
                Debug.LogError($"[TR-01c] Could not save {scenePath}.");
                return;
            }
            AssetDatabase.SaveAssets();
            Debug.Log($"[TR-01c] {scenePath}: {rivals} rival(s); {string.Join("; ", log)}");
        }

        // ================================================================== steps

        /// <summary>
        /// Drops closable ids that are not a Shortcut-kind route (e.g. the "cave" of the old defaults: it sits on the only
        /// river route, so closing it would cut that route). The asset is fixed in place so the runner can never pick it.
        /// </summary>
        private static void SanitiseVariation(WorldVariationConfig variation, TerrainLayoutData layout, List<string> log)
        {
            string[] ids = variation.shortcutIds ?? Array.Empty<string>();
            var kept = new List<string>(ids.Length);
            foreach (string id in ids)
            {
                bool isShortcut = layout.routes != null && Array.Exists(layout.routes,
                    r => r.kind == RouteKind.Shortcut && r.shortcutId == id);
                bool onMain = layout.routes != null && Array.Exists(layout.routes,
                    r => r.kind == RouteKind.Main && r.shortcutId == id);
                if (isShortcut && !onMain) kept.Add(id);
                else log.Add($"removed closable id '{id}' (not a shortcut route)");
            }
            if (kept.Count == ids.Length) return;
            variation.shortcutIds = kept.ToArray();
            variation.maxOpenShortcuts = Mathf.Clamp(variation.maxOpenShortcuts, 1, Mathf.Max(1, kept.Count));
            variation.minOpenShortcuts = Mathf.Clamp(variation.minOpenShortcuts, 1, variation.maxOpenShortcuts);
            EditorUtility.SetDirty(variation);
        }

        private static void CheckTerrainMatches(Scene scene, HeightField heights, TerrainLayoutData layout, List<string> log)
        {
            GameObject terrainGo = FindRoot(scene, ParamoTerrainGenerator.TerrainObjectName);
            Terrain terrain = terrainGo != null ? terrainGo.GetComponent<Terrain>() : null;
            if (terrain == null)
            {
                log.Add("WARNING no terrain found");
                return;
            }
            float worst = 0f;
            foreach (RouteDef r in layout.routes)
            {
                if (r.nodes == null) continue;
                foreach (Vector2 n in r.nodes)
                {
                    var p = new Vector3(n.x, 0f, n.y);
                    float y = terrain.SampleHeight(p) + terrain.transform.position.y;
                    worst = Mathf.Max(worst, Mathf.Abs(y - heights.Sample(n.x, n.y)));
                }
            }
            if (worst > TerrainMismatchTolerance)
                Debug.LogWarning($"[TR-01c] Terrain differs from the layout by up to {worst:0.0} m at route nodes: re-run " +
                                 "Convoy/Terrain/Generate Páramo_01, then this setup.");
        }

        private static void SetupWorldVariation(Transform root, Transform generated, WorldVariationConfig variation,
            TerrainLayoutData layout, List<string> log)
        {
            Transform host = AiRivalSetup.EnsureGroup(root, WorldName);

            // Blockers in config order (bit i of the open mask = shortcutIds[i]).
            Transform blockerGroup = generated.Find("ShortcutBlockers");
            string[] ids = variation.shortcutIds ?? Array.Empty<string>();
            var blockers = new GameObject[ids.Length];
            for (int i = 0; i < ids.Length; i++)
            {
                Transform b = blockerGroup != null ? blockerGroup.Find($"Blocker_{ids[i]}") : null;
                blockers[i] = b != null ? b.gameObject : null;
                if (b == null) log.Add($"WARNING no Blocker_{ids[i]}");
            }

            // Mine slots in index order (MineSlot_00, _01, ...): names sort the same way the generator numbered them.
            Transform mineGroup = generated.Find("MineSlots");
            var mines = new List<GameObject>();
            if (mineGroup != null)
                foreach (Transform m in mineGroup) mines.Add(m.gameObject);
            mines.Sort((a, b) => string.CompareOrdinal(a.name, b.name));

            var runner = host.GetComponent<WorldVariationRunner>();
            if (runner == null) runner = host.gameObject.AddComponent<WorldVariationRunner>();
            var so = new SerializedObject(runner);
            so.FindProperty("_config").objectReferenceValue = variation;
            SetObjects(so.FindProperty("_shortcutBlockers"), blockers);
            SetObjects(so.FindProperty("_mineSlots"), mines.ToArray());
            so.FindProperty("_laneDir").vector2Value = MinefieldLaneDir(layout, variation.minefieldCentre);
            so.ApplyModifiedPropertiesWithoutUndo();

            var atmosphere = host.GetComponent<ParamoAtmosphere>();
            if (atmosphere == null) atmosphere = host.gameObject.AddComponent<ParamoAtmosphere>();
            var aso = new SerializedObject(atmosphere);
            aso.FindProperty("_runner").objectReferenceValue = runner;
            aso.FindProperty("_config").objectReferenceValue = variation;
            aso.ApplyModifiedPropertiesWithoutUndo();

            log.Add($"world variation: {ids.Length} closable shortcut(s) [{string.Join(", ", ids)}], {mines.Count} mine slot(s)");
        }

        /// <summary>Direction of travel of the main road nearest the minefield centre (safe lanes run along it).</summary>
        private static Vector2 MinefieldLaneDir(TerrainLayoutData layout, Vector2 centre)
        {
            float best = float.PositiveInfinity;
            Vector2 dir = Vector2.up;
            foreach (RouteDef r in layout.routes)
            {
                if (r.kind != RouteKind.Main || r.nodes == null) continue;
                for (int k = 0; k < r.nodes.Length - 1; k++)
                {
                    Vector2 a = r.nodes[k], ab = r.nodes[k + 1] - a;
                    if (ab.sqrMagnitude < 1e-6f) continue;
                    float t = Mathf.Clamp01(Vector2.Dot(centre - a, ab) / ab.sqrMagnitude);
                    float d = (centre - (a + ab * t)).sqrMagnitude;
                    if (d >= best) continue;
                    best = d;
                    dir = ab.normalized;
                }
            }
            return dir;
        }

        private static int SetupRivals(Transform root, TerrainLayoutData layout, HeightField heights, VehicleController player,
            List<string> log)
        {
            AiDriverProfile[] profiles = AiRivalSetup.EnsureProfiles();
            Transform lines = AiRivalSetup.EnsureGroup(root, LinesGroup);
            Transform rivals = AiRivalSetup.EnsureGroup(root, RivalsGroup);
            if (player == null) log.Add("WARNING no player Jackal: rivals start without waiting");

            var waypoints = new List<Vector3>(128);
            int count = 0;
            foreach (RouteDef r in layout.routes)
            {
                if (r.kind != RouteKind.Rival) continue;
                int n = RivalRouteExport.Waypoints(heights, r, RivalWaypointSpacing, layout.crater.centre,
                    layout.crater.plateauRadius, waypoints);
                if (n < 2)
                {
                    log.Add($"WARNING rival route {r.id} too short");
                    continue;
                }
                RacingLine line = AiRivalSetup.EnsureRacingLine(lines, $"RacingLine_{r.id}", waypoints,
                    Mathf.Max(0.5f, r.width * 0.5f - RivalLaneEdgeMargin));
                // Steady, Balanced, Aggressive in route order (W, N, E in the defaults): three visibly different drivers.
                AiDriverProfile profile = profiles[count % profiles.Length];
                AiPilot pilot = AiRivalSetup.EnsureRival(rivals, RivalName(r.id), AiRivalSetup.StartPose(waypoints), line,
                    profile, player);
                if (pilot != null) count++;
            }
            return count;
        }

        /// <summary>"rival_w" → "Rival_W" (matches the generator's Spawn_Rival_W naming).</summary>
        private static string RivalName(string routeId)
        {
            string id = routeId ?? string.Empty;
            int cut = id.IndexOf('_');
            return "Rival_" + (cut >= 0 ? id.Substring(cut + 1) : id).ToUpperInvariant();
        }

        private static void SetupRecovery(VehicleController player, TerrainLayoutData layout, HeightField heights, List<string> log)
        {
            if (player == null)
            {
                log.Add("WARNING no player Jackal: recovery points not added");
                return;
            }

            var points = new List<Vector3>(2048);
            var starts = new List<int>(16);
            var sample = new List<Vector3>(1024);
            foreach (RouteDef r in layout.routes)
            {
                if (r.kind == RouteKind.Rival) continue; // the player's roads only (spec: Main + Shortcut)
                TerrainSynthesis.SampleRoute(heights, r, RecoverySpacing, sample);
                bool open = false;
                foreach (Vector3 p in sample)
                {
                    if (InChasmExclusion(layout.chasm, new Vector2(p.x, p.z)))
                    {
                        open = false; // the road continues past the hole as a separate piece
                        continue;
                    }
                    if (!open)
                    {
                        starts.Add(points.Count);
                        open = true;
                    }
                    points.Add(p);
                }
            }

            var recovery = player.GetComponent<RouteRecoveryPoints>();
            if (recovery == null) recovery = player.gameObject.AddComponent<RouteRecoveryPoints>();
            var so = new SerializedObject(recovery);
            so.FindProperty("_body").objectReferenceValue = player.GetComponent<Rigidbody>();
            SetVectors(so.FindProperty("_routePoints"), points);
            SetInts(so.FindProperty("_routeStarts"), starts);
            so.ApplyModifiedPropertiesWithoutUndo();
            if (PrefabUtility.IsPartOfPrefabInstance(recovery)) PrefabUtility.RecordPrefabInstancePropertyModifications(recovery);
            log.Add($"recovery: {points.Count} points in {starts.Count} road piece(s)");
        }

        /// <summary>The chasm gap and its landing run-out, across the full cut width plus a margin.</summary>
        private static bool InChasmExclusion(ChasmDef c, Vector2 p)
        {
            if (c.gapWidth <= 0f || c.depth <= 0f) return false;
            float yaw = c.yawDeg * Mathf.Deg2Rad;
            var fwd = new Vector2(Mathf.Sin(yaw), Mathf.Cos(yaw));
            var right = new Vector2(fwd.y, -fwd.x);
            Vector2 rel = p - c.centre;
            float along = Vector2.Dot(rel, fwd), across = Vector2.Dot(rel, right);
            float half = c.gapWidth * 0.5f;
            return along >= -half - ChasmEdgeMargin && along <= half + ChasmLandingExclusion
                && Mathf.Abs(across) <= c.length * 0.5f + ChasmEdgeMargin;
        }

        // ================================================================== helpers

        private static bool OpenScene(string scenePath, out Scene scene)
        {
            scene = SceneManager.GetActiveScene();
            if (scene.IsValid() && scene.isLoaded && scene.path == scenePath) return true;
            // Why: opening a scene in Single mode unloads the current one; let a human save first (no-op if clean).
            if (!Application.isBatchMode && !EditorSceneManager.SaveCurrentModifiedScenesIfUserWantsTo())
            {
                Debug.LogWarning("[TR-01c] Cancelled: unsaved scene changes were not resolved.");
                return false;
            }
            scene = EditorSceneManager.OpenScene(scenePath, OpenSceneMode.Single);
            return scene.IsValid();
        }

        private static GameObject FindRoot(Scene scene, string name)
        {
            foreach (GameObject go in scene.GetRootGameObjects())
                if (go.name == name) return go;
            return null;
        }

        private static VehicleController FindPlayer(Scene scene)
        {
            GameObject go = FindRoot(scene, PlayerName);
            return go != null ? go.GetComponentInChildren<VehicleController>(true) : null;
        }

        private static void SetObjects(SerializedProperty array, Object[] values)
        {
            array.arraySize = values.Length;
            for (int i = 0; i < values.Length; i++) array.GetArrayElementAtIndex(i).objectReferenceValue = values[i];
        }

        private static void SetVectors(SerializedProperty array, List<Vector3> values)
        {
            array.arraySize = values.Count;
            for (int i = 0; i < values.Count; i++) array.GetArrayElementAtIndex(i).vector3Value = values[i];
        }

        private static void SetInts(SerializedProperty array, List<int> values)
        {
            array.arraySize = values.Count;
            for (int i = 0; i < values.Count; i++) array.GetArrayElementAtIndex(i).intValue = values[i];
        }
    }
}
